result=[]
for id,title,duration,audience,scenes in sets:
 assert len(scenes)*30==duration
 for s in scenes:
  assert len(s['events'])==4 and 50<=len(''.join(e['text'] for e in s['events']))<=130,(id,s)
 result.append({'id':id,'title':title,'topic':title,'config':{'duration':duration,'audience':audience,'voice':True},'scenes':scenes})
Path('scripts/course-whiteboard/reference-content.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
